async function bootLedgerly(){
  try {
    const [clients, invoices, profile, integrationRecords] = await Promise.all([api.clients(), api.invoices(), api.profile(), api.integrations()]);
    S.cs = clients.map(client => client.name);
    S.clientIds = clients.map(client => client.id);
    S.cd = clients.map(client => ({ e: client.email, p: client.phone || '', a: client.address || '' }));
    S.inv = invoices.map(invoice => ({ id: invoice.number, c: Math.max(0, clients.findIndex(client => client.id === invoice.client_id)), a: Number(invoice.amount), due: invoice.due_date || '', s: invoice.status, rec: false, cur: invoice.currency || 'USD', n: invoice.payment_instructions || '' }));
    S.biz = profile.name ? [{ n: profile.name, a: profile.address || '', e: profile.email || '', p: profile.phone || '' }] : [{ n: 'Your business', a: '', e: '', p: '' }];
    S.ints = Object.fromEntries(integrationRecords.map(record => [record.provider, { on: record.status === 'connected', acct: record.account_label || '' }]));
  } catch (error) {
    console.error('Ledgerly API bootstrap failed', error);
  }
  render();
}
save = async function(mode){
  const e = S.ed, errors = [];
  if (e.c === '') errors.push('Choose a client to bill.');
  if (!e.items.some(item => Number(item.p) > 0)) errors.push('Add at least one line item with a price.');
  if (!e.due) errors.push('Pick a due date.');
  e.err = errors;
  if (errors.length) return render();
  const total = calc().tot;
  const response = await fetch('/api/invoices', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ clientId: S.clientIds?.[Number(e.c)], description: e.items.filter(item => item.d || item.p > 0).map(item => item.d || 'Line item').join(', '), amount: total, dueDate: e.due, currency: e.cur, paymentInstructions: e.n }) });
  const invoice = await response.json();
  if (!response.ok) { e.err = [invoice.error || 'Unable to save invoice.']; return render(); }
  if (mode === 'pdf') {
    const pdf = await fetch(`/api/invoices/${invoice.number}/pdf`);
    const blob = await pdf.blob();
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a'); link.href = url; link.download = `${invoice.number}.pdf`; link.click(); URL.revokeObjectURL(url);
  }
  S.ed = null; S.r = 'invoices'; S.tab = 'All'; toast(mode === 'pdf' ? `${invoice.number} saved. PDF downloaded` : `${invoice.number} saved as draft`);
};
